package chargen_test

import (
	"testing"

	"github.com/philoserf/ctchargen/internal/chargen"
	"github.com/philoserf/ctchargen/internal/traveller"
)

// A fixture is a scripted sequence of dice and draws that walks the
// procedure down one chosen path, named for the path it reaches. Its golden
// is the record it generates.
//
// The lists were extracted once from each golden's own event log, which
// records every die of every roll and throw in order, and every draw as the
// choice it produced. The proof the extraction was right is that every golden
// regenerated byte-identical. A script is consumed exactly, so a procedure
// change that consumes a different number of dice fails the fixture that felt
// it: one that asks for more names the die asked for, and one that asks for
// fewer names what it left unread.
type fixture struct {
	name    string
	service traveller.ServiceName
	forced  bool
	policy  chargen.Policy
	dice    []int // every die, in the order the procedure asks for it
	among   []int // every draw among alternatives, as an index into the offer
}

func (f fixture) inputs() chargen.Inputs {
	return chargen.Inputs{
		Service: f.service, Forced: f.forced,
		Career: f.policy.Career, Skills: f.policy.Skills, Muster: f.policy.Muster,
	}
}

func (f fixture) generate(t *testing.T) *chargen.Character {
	t.Helper()

	character, err := f.run(t)
	if err != nil {
		t.Fatalf("%s: %v", f.name, err)
	}

	return character
}

// run walks the fixture's path under its own policy, and, when the procedure
// finishes, fails if the script holds a die or a draw it never asked for. A
// run that ends in an error stopped early, and its unread tail says nothing.
func (f fixture) run(t *testing.T, options ...chargen.Option) (*chargen.Character, error) {
	t.Helper()

	roller := f.roller(t)

	character, err := chargen.Generate(f.inputs(), f.policy, append(options, chargen.WithRoller(roller))...)
	if err != nil {
		return nil, err //nolint:wrapcheck // the engine's own error, for the caller to judge
	}

	roller.finished()

	return character, nil
}

func (f fixture) roller(t *testing.T) *scripted {
	t.Helper()

	return &scripted{t: t, name: f.name, dice: f.dice, among: f.among}
}

// scripted is the roller a fixture drives. It hands out the fixture's dice
// and draws in order and refuses to be asked for more than it was given: a
// die the fixture does not script would otherwise be answered with a value
// nobody chose, and the golden would move without saying which throw moved.
type scripted struct {
	t     *testing.T
	name  string
	dice  []int
	among []int
	die   int // dice handed out so far
	draw  int // draws handed out so far
}

func (s *scripted) Die() int {
	s.t.Helper()

	if s.die == len(s.dice) {
		s.t.Fatalf("%s: the procedure asked for die %d, and the fixture scripts %d",
			s.name, s.die+1, len(s.dice))
	}

	face := s.dice[s.die]
	s.die++

	return face
}

func (s *scripted) TwoDice() (int, int) {
	s.t.Helper()

	first := s.Die()
	second := s.Die()

	return first, second
}

func (s *scripted) Among(n int) int {
	s.t.Helper()

	if s.draw == len(s.among) {
		s.t.Fatalf("%s: the procedure asked for draw %d, and the fixture scripts %d",
			s.name, s.draw+1, len(s.among))
	}

	index := s.among[s.draw]
	s.draw++

	if index >= n {
		s.t.Fatalf("%s: draw %d is index %d of %d alternatives", s.name, s.draw, index, n)
	}

	return index
}

// finished fails if the procedure left any of the script unread, naming how
// much and where it starts.
func (s *scripted) finished() {
	s.t.Helper()

	if s.die < len(s.dice) {
		s.t.Errorf("%s: the procedure finished with %d of the fixture's %d dice unread, from die %d",
			s.name, len(s.dice)-s.die, len(s.dice), s.die+1)
	}

	if s.draw < len(s.among) {
		s.t.Errorf("%s: the procedure finished with %d of the fixture's %d draws unread, from draw %d",
			s.name, len(s.among)-s.draw, len(s.among), s.draw+1)
	}
}

