// byName finds a fixture on the roster, for a test that holds a rule the
// fixture's path reaches and wants the character rather than the golden.
func byName(t *testing.T, name string) fixture {
	t.Helper()

	for _, f := range fixtures {
		if f.name == name {
			return f
		}
	}

	t.Fatalf("no fixture named %q on the roster", name)

	return fixture{}
}
